                 //                        "maxPrice": "10000000.00000000",
                 //                        "tickSize": "0.01",
                 //                        "filterType": "PRICE_FILTER"
                 //                    },
                 //                    {
                 //                        "minQty": "0.0001",
                 //                        "maxQty": "4000",
