                 //                         "quantity": "84000.0",
                 //                         "initialMargin": "0.04",
                 //                         "maintMargin": "0.02",
                 //                         "isWhite": false
                 //                     },
                 //                     ...
                 //                 ]
                 //            },
                 //        ],
                 //        "coins": [
                 //            {
                 //                "orgId": "9001",
                 //                "coinId": "TCOM",
                 //                "coinName": "TCOM",
                 //                "coinFullName": "TCOM",
                 //                "allowWithdraw": true,
                 //                "allowDeposit": true,
                 //                "chainTypes": [
                 //                    {
                 //                        "chainType": "BSC",
                 //                        "withdrawFee": "49.55478",
                 //                        "minWithdrawQuantity": "77",
                 //                        "maxWithdrawQuantity": "0",
                 //                        "minDepositQuantity": "48",
                 //                        "allowDeposit": true,
                 //                        "allowWithdraw": false
